// app/actions/user-analytics.ts
'use server';

import { z } from 'zod';
import { db } from '@/lib/db';
import { revalidatePath } from 'next/cache';

const UpdateMetricSchema = z.object({
  userId: z.string().uuid(),
  delta: z.number().int().min(1),
});

type ActionState = 
  | { status: 'idle' }
  | { status: 'success'; data: { updatedCount: number } }
  | { status: 'error'; message: string };

export async function incrementUserScore(
  prevState: ActionState,
  formData: FormData
): Promise<ActionState> {
  const parse = UpdateMetricSchema.safeParse({
    userId: formData.get('userId'),
    delta: Number(formData.get('delta')),
  });

  if (!parse.success) {
    return { status: 'error', message: '参数格式不合法，更新已终止' };
  }

  try {
    const record = await db.metric.update({
      where: { id: parse.data.userId },
      data: { score: { increment: parse.data.delta } },
      select: { score: true },
    });
    revalidatePath('/dashboard/metrics');
    return { status: 'success', data: { updatedCount: record.score } };
  } catch (error) {
    console.error('[MetricSyncError]', error);
    return { status: 'error', message: '数据库执行失败，请稍后重试' };
  }
}

/* 推演结论：在 Goroutine A 持有 Lock1 请求 Lock2 的同时，Goroutine B 持有 Lock2 请求 Lock1，导致经典死锁循环。
   优化方案：废弃双互斥锁，改用无锁 CAS (Compare-And-Swap) 或通道序列化处理 */

package main

import (
	"sync/atomic"
	"unsafe"
)

type LockFreeQueue struct {
	head unsafe.Pointer
	tail unsafe.Pointer
}

type node struct {
	value interface{}
	next  unsafe.Pointer
}

func NewLockFreeQueue() *LockFreeQueue {
	n := unsafe.Pointer(&node{})
	return &LockFreeQueue{head: n, tail: n}
}

func (q *LockFreeQueue) Enqueue(v interface{}) {
	n := &node{value: v}
	for {
		tail := q.tail
		next := (*node)(tail).next
		if tail == q.tail {
			if next == nil {
				if atomic.CompareAndSwapPointer(&(*node)(tail).next, next, unsafe.Pointer(n)) {
					atomic.CompareAndSwapPointer(&q.tail, tail, unsafe.Pointer(n))
					return
				}
			} else {
				atomic.CompareAndSwapPointer(&q.tail, tail, next)
			}
		}
	}
}
